arguments.content:
terraform {
  required_version = ">= 1.6.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region                      = var.region
  access_key                  = "test"
  secret_key                  = "test"
  skip_credentials_validation = true
  skip_metadata_api_check     = true
  skip_region_validation      = true
  skip_requesting_account_id  = false
  s3_use_path_style           = true

  endpoints {
    acm              = var.aws_endpoint_url
    cloudwatch       = var.aws_endpoint_url
    cloudwatchlogs   = var.aws_endpoint_url
    cognitoidp       = var.aws_endpoint_url
    dynamodb         = var.aws_endpoint_url
    ec2              = var.aws_endpoint_url
    ecs              = var.aws_endpoint_url
    elasticache      = var.aws_endpoint_url
    elbv2            = var.aws_endpoint_url
    events           = var.aws_endpoint_url
    iam              = var.aws_endpoint_url
    kms              = var.aws_endpoint_url
    lambda           = var.aws_endpoint_url
    rds              = var.aws_endpoint_url
    s3               = var.aws_endpoint_url
    scheduler        = var.aws_endpoint_url
    secretsmanager   = var.aws_endpoint_url
    sqs              = var.aws_endpoint_url
    ssm              = var.aws_endpoint_url
    sts              = var.aws_endpoint_url
  }

  default_tags {
    tags = {
      ClearLedgerDeployment = var.resource_prefix
    }
  }
}

variable "resource_prefix" {
  type = string
}

variable "region" {
  type    = string
  default = "us-east-1"
}

variable "aws_endpoint_url" {
  type    = string
  default = "http://aws:4566"
}

variable "db_name" {
  type = string
}

variable "db_username" {
  type = string
}

variable "db_password" {
  type      = string
  sensitive = true
}

variable "api_image" {
  type = string
}

variable "projector_image" {
  type = string
}

variable "relay_image" {
  type = string
}

variable "archiver_image" {
  type = string
}

variable "api_image_id" {
  type    = string
  default = ""
}

variable "projector_image_id" {
  type    = string
  default = ""
}

variable "relay_image_id" {
  type    = string
  default = ""
}

variable "archiver_image_id" {
  type    = string
  default = ""
}

variable "vpc_cidr" {
  type    = string
  default = "10.42.0.0/16"
}

locals {
  p       = var.resource_prefix
  azs     = ["${var.region}a", "${var.region}b"]
  account = data.aws_caller_identity.current.account_id
  tags    = { ClearLedgerDeployment = var.resource_prefix }

  # Endpoint reachable from inside the workload containers.
  container_aws_endpoint = var.aws_endpoint_url
}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = merge(local.tags, { Name = "${local.p}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.tags, { Name = "${local.p}-igw" })
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true
  tags                    = merge(local.tags, { Name = "${local.p}-public-${local.azs[count.index]}", Tier = "public" })
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index + 10)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false
  tags                    = merge(local.tags, { Name = "${local.p}-private-${local.azs[count.index]}", Tier = "private" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.tags, { Name = "${local.p}-public-rt" })
}

resource "aws_route" "public_default" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.tags, { Name = "${local.p}-private-rt" })
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Security groups (inline rules so Terraform owns the full rule set and
# reverts out-of-band additions on every apply).
# ---------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name        = "${local.p}-alb"
  description = "ClearLedger ALB - HTTP in, 8080 to ECS only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "To API tasks on 8080 inside the VPC"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.tags, { Name = "${local.p}-alb" })
}

resource "aws_security_group" "ecs" {
  name        = "${local.p}-ecs"
  description = "ClearLedger API tasks and workers"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "API from ALB"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Outbound to AWS control plane and data stores"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.tags, { Name = "${local.p}-ecs" })
}

resource "aws_security_group" "rds" {
  name        = "${local.p}-rds"
  description = "ClearLedger PostgreSQL"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from workloads"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  egress = []

  tags = merge(local.tags, { Name = "${local.p}-rds" })
}

resource "aws_security_group" "valkey" {
  name        = "${local.p}-valkey"
  description = "ClearLedger Valkey cache"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Valkey from workloads"
    from_port       = 6379
    to_port         = 6379
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  egress = []

  tags = merge(local.tags, { Name = "${local.p}-valkey" })
}

locals {
  kms_purposes = {
    database   = "RDS PostgreSQL storage encryption"
    messaging  = "SQS main queue and DLQ encryption"
    projection = "DynamoDB projection table encryption"
    audit      = "S3 audit archive encryption"
  }

  log_groups = {
    api       = "/clearledger/${local.p}/api"
    projector = "/clearledger/${local.p}/projector"
    relay     = "/clearledger/${local.p}/outbox-relay"
    archiver  = "/clearledger/${local.p}/audit-archiver"
  }
}

resource "aws_kms_key" "this" {
  for_each                = local.kms_purposes
  description             = "${local.p}-${each.key}: ${each.value}"
  enable_key_rotation     = true
  deletion_window_in_days = 10
  tags                    = merge(local.tags, { Name = "${local.p}-${each.key}" })
}

resource "aws_kms_alias" "this" {
  for_each      = local.kms_purposes
  name          = "alias/${local.p}-${each.key}"
  target_key_id = aws_kms_key.this[each.key].key_id
}

resource "aws_cloudwatch_log_group" "this" {
  for_each          = local.log_groups
  name              = each.value
  retention_in_days = 14
  tags              = merge(local.tags, { Name = "${local.p}-${each.key}-logs" })
}

# ---------------------------------------------------------------------------
# RDS PostgreSQL
# ---------------------------------------------------------------------------
resource "aws_db_subnet_group" "main" {
  name       = "${local.p}-db-subnets"
  subnet_ids = aws_subnet.private[*].id
  tags       = merge(local.tags, { Name = "${local.p}-db-subnets" })
}

resource "aws_db_instance" "main" {
  identifier             = "${local.p}-postgres"
  engine                 = "postgres"
  engine_version         = "16.3"
  instance_class         = "db.t4g.micro"
  allocated_storage      = 20
  db_name                = var.db_name
  username               = var.db_username
  password               = var.db_password
  port                   = 5432
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.this["database"].arn
  publicly_accessible    = false
  skip_final_snapshot    = true
  deletion_protection    = false
  apply_immediately      = true
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  tags                   = merge(local.tags, { Name = "${local.p}-postgres" })

  lifecycle {
    # Never replace the system-of-record because of emulator-side
    # normalisation of immutable attributes.
    ignore_changes = [engine_version, kms_key_id, storage_encrypted, db_name, username, allocated_storage, db_subnet_group_name]
  }
}

# ---------------------------------------------------------------------------
# DynamoDB projection store
# ---------------------------------------------------------------------------
resource "aws_dynamodb_table" "projection" {
  name         = "${local.p}-projections"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "PK"
  range_key    = "SK"

  attribute {
    name = "PK"
    type = "S"
  }
  attribute {
    name = "SK"
    type = "S"
  }
  attribute {
    name = "GSI1PK"
    type = "S"
  }
  attribute {
    name = "GSI1SK"
    type = "S"
  }

  global_secondary_index {
    name            = "AccountIndex"
    hash_key        = "GSI1PK"
    range_key       = "GSI1SK"
    projection_type = "ALL"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.this["projection"].arn
  }

  tags = merge(local.tags, { Name = "${local.p}-projections" })
}

# ---------------------------------------------------------------------------
# ElastiCache for Valkey
# ---------------------------------------------------------------------------
resource "aws_elasticache_subnet_group" "main" {
  name       = "${local.p}-cache-subnets"
  subnet_ids = aws_subnet.private[*].id
  tags       = merge(local.tags, { Name = "${local.p}-cache-subnets" })
}

resource "aws_elasticache_replication_group" "valkey" {
  replication_group_id       = "${local.p}-valkey"
  description                = "ClearLedger projection cache"
  engine                     = "valkey"
  engine_version             = "8.0"
  node_type                  = "cache.t4g.micro"
  num_cache_clusters         = 1
  port                       = 6379
  subnet_group_name          = aws_elasticache_subnet_group.main.name
  security_group_ids         = [aws_security_group.valkey.id]
  automatic_failover_enabled = false
  transit_encryption_enabled = false
  at_rest_encryption_enabled = false
  apply_immediately          = true
  tags                       = merge(local.tags, { Name = "${local.p}-valkey" })
}

# ---------------------------------------------------------------------------
# S3 audit archive
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "audit" {
  bucket        = "${local.p}-ledger-audit-${local.account}"
  force_destroy = true
  tags          = merge(local.tags, { Name = "${local.p}-ledger-audit" })
}

resource "aws_s3_bucket_versioning" "audit" {
  bucket = aws_s3_bucket.audit.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "audit" {
  bucket = aws_s3_bucket.audit.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this["audit"].arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "audit" {
  bucket                  = aws_s3_bucket.audit.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# SQS main queue + DLQ
# ---------------------------------------------------------------------------
resource "aws_sqs_queue" "dlq" {
  name                              = "${local.p}-settlement-events-dlq"
  kms_master_key_id                 = aws_kms_key.this["messaging"].arn
  kms_data_key_reuse_period_seconds = 300
  message_retention_seconds         = 1209600
  tags                              = merge(local.tags, { Name = "${local.p}-settlement-events-dlq" })
}

resource "aws_sqs_queue" "main" {
  name                              = "${local.p}-settlement-events"
  kms_master_key_id                 = aws_kms_key.this["messaging"].arn
  kms_data_key_reuse_period_seconds = 300
  visibility_timeout_seconds        = 3
  receive_wait_time_seconds         = 2
  message_retention_seconds         = 172800
  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq.arn
    maxReceiveCount     = 4
  })
  tags = merge(local.tags, { Name = "${local.p}-settlement-events" })
}

locals {
  kms_arn = { for k, v in aws_kms_key.this : k => v.arn }

  lg_arn = { for k, v in aws_cloudwatch_log_group.this : k => "arn:aws:logs:${var.region}:${local.account}:log-group:${v.name}" }
  # Own-log-group resources (group ARN and its streams).
  lg_res = { for k, v in local.lg_arn : k => [v, "${v}:*", "${v}:log-stream:*"] }

  table_arn = aws_dynamodb_table.projection.arn
  gsi_arn   = "${aws_dynamodb_table.projection.arn}/index/AccountIndex"
  bucket    = aws_s3_bucket.audit.arn

  sqs_all_actions  = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]
  ddb_all_actions  = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:Query"]
  s3_all_actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]
  kms_use_actions  = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
  kms_deny_actions = ["kms:Decrypt", "kms:GenerateDataKey"]
  logs_write       = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"]
  logs_deny        = ["logs:CreateLogStream", "logs:PutLogEvents"]

  other_logs = {
    for k in keys(local.log_groups) : k => flatten([for o, r in local.lg_res : r if o != k])
  }
  all_logs = flatten(values(local.lg_res))

  lambda_trust = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
  ecs_trust = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ecs-tasks.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
  scheduler_trust = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "scheduler.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

# ---------------------------------------------------------------------------
# Roles
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_execution" {
  name               = "${local.p}-ecs-execution"
  assume_role_policy = local.ecs_trust
  tags               = merge(local.tags, { Name = "${local.p}-ecs-execution" })
}

resource "aws_iam_role" "ecs_task" {
  name               = "${local.p}-ecs-task"
  assume_role_policy = local.ecs_trust
  tags               = merge(local.tags, { Name = "${local.p}-ecs-task" })
}

resource "aws_iam_role" "projector" {
  name               = "${local.p}-projector"
  assume_role_policy = local.lambda_trust
  tags               = merge(local.tags, { Name = "${local.p}-projector" })
}

resource "aws_iam_role" "relay" {
  name               = "${local.p}-outbox-relay"
  assume_role_policy = local.lambda_trust
  tags               = merge(local.tags, { Name = "${local.p}-outbox-relay" })
}

resource "aws_iam_role" "archiver" {
  name               = "${local.p}-audit-archiver"
  assume_role_policy = local.lambda_trust
  tags               = merge(local.tags, { Name = "${local.p}-audit-archiver" })
}

resource "aws_iam_role" "scheduler" {
  name               = "${local.p}-scheduler"
  assume_role_policy = local.scheduler_trust
  tags               = merge(local.tags, { Name = "${local.p}-scheduler" })
}

# ---------------------------------------------------------------------------
# ecs_execution: write API logs only.
# ---------------------------------------------------------------------------
resource "aws_iam_role_policy" "ecs_execution" {
  name = "${local.p}-ecs-execution-policy"
  role = aws_iam_role.ecs_execution.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ApiLogsWrite"
        Effect   = "Allow"
        Action   = local.logs_write
        Resource = local.lg_res["api"]
      },
      {
        Sid      = "DenySqs"
        Effect   = "Deny"
        Action   = local.sqs_all_actions
        Resource = [aws_sqs_queue.main.arn, aws_sqs_queue.dlq.arn]
      },
      {
        Sid      = "DenyDynamoDb"
        Effect   = "Deny"
        Action   = local.ddb_all_actions
        Resource = [local.table_arn, local.gsi_arn]
      },
      {
        Sid      = "DenyS3"
        Effect   = "Deny"
        Action   = local.s3_all_actions
        Resource = [local.bucket, "${local.bucket}/*"]
      },
      {
        Sid      = "DenyKms"
        Effect   = "Deny"
        Action   = local.kms_deny_actions
        Resource = values(local.kms_arn)
      },
      {
        Sid      = "DenyOtherLogs"
        Effect   = "Deny"
        Action   = local.logs_deny
        Resource = local.other_logs["api"]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# ecs_task: API runtime permissions.
# ---------------------------------------------------------------------------
resource "aws_iam_role_policy" "ecs_task" {
  name = "${local.p}-ecs-task-policy"
  role = aws_iam_role.ecs_task.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "PublishMainQueue"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"]
        Resource = [aws_sqs_queue.main.arn]
      },
      {
        Sid      = "ReadProjections"
        Effect   = "Allow"
        Action   = ["dynamodb:GetItem", "dynamodb:Query", "dynamodb:DescribeTable"]
        Resource = [local.table_arn, local.gsi_arn]
      },
      {
        Sid      = "KmsMessagingProjection"
        Effect   = "Allow"
        Action   = local.kms_use_actions
        Resource = [local.kms_arn["messaging"], local.kms_arn["projection"]]
      },
      {
        Sid      = "ApiLogsWrite"
        Effect   = "Allow"
        Action   = local.logs_write
        Resource = local.lg_res["api"]
      },
      {
        Sid      = "DenyConsumeMainQueue"
        Effect   = "Deny"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [aws_sqs_queue.main.arn]
      },
      {
        Sid      = "DenyDlq"
        Effect   = "Deny"
        Action   = local.sqs_all_actions
        Resource = [aws_sqs_queue.dlq.arn]
      },
      {
        Sid      = "DenyDynamoDbMutation"
        Effect   = "Deny"
        Action   = ["dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:DeleteTable"]
        Resource = [local.table_arn, local.gsi_arn]
      },
      {
        Sid      = "DenyS3"
        Effect   = "Deny"
        Action   = local.s3_all_actions
        Resource = [local.bucket, "${local.bucket}/*"]
      },
      {
        Sid      = "DenyKmsDatabaseAudit"
        Effect   = "Deny"
        Action   = local.kms_deny_actions
        Resource = [local.kms_arn["database"], local.kms_arn["audit"]]
      },
      {
        Sid      = "DenyOtherLogs"
        Effect   = "Deny"
        Action   = local.logs_deny
        Resource = local.other_logs["api"]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# projector
# ---------------------------------------------------------------------------
resource "aws_iam_role_policy" "projector" {
  name = "${local.p}-projector-policy"
  role = aws_iam_role.projector.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ConsumeMainQueue"
        Effect   = "Allow"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes", "sqs:ChangeMessageVisibility"]
        Resource = [aws_sqs_queue.main.arn]
      },
      {
        Sid      = "ForwardToDlq"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage"]
        Resource = [aws_sqs_queue.dlq.arn]
      },
      {
        Sid      = "UpsertProjections"
        Effect   = "Allow"
        Action   = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:Query"]
        Resource = [local.table_arn, local.gsi_arn]
      },
      {
        Sid      = "KmsMessagingProjection"
        Effect   = "Allow"
        Action   = local.kms_use_actions
        Resource = [local.kms_arn["messaging"], local.kms_arn["projection"]]
      },
      {
        Sid      = "ProjectorLogsWrite"
        Effect   = "Allow"
        Action   = local.logs_write
        Resource = local.lg_res["projector"]
      },
      {
        Sid      = "DenyPublishMainQueue"
        Effect   = "Deny"
        Action   = ["sqs:SendMessage"]
        Resource = [aws_sqs_queue.main.arn]
      },
      {
        Sid      = "DenyConsumeDlq"
        Effect   = "Deny"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [aws_sqs_queue.dlq.arn]
      },
      {
        Sid      = "DenyDynamoDbDelete"
        Effect   = "Deny"
        Action   = ["dynamodb:DeleteItem", "dynamodb:DeleteTable"]
        Resource = [local.table_arn, local.gsi_arn]
      },
      {
        Sid      = "DenyS3"
        Effect   = "Deny"
        Action   = local.s3_all_actions
        Resource = [local.bucket, "${local.bucket}/*"]
      },
      {
        Sid      = "DenyKmsDatabaseAudit"
        Effect   = "Deny"
        Action   = local.kms_deny_actions
        Resource = [local.kms_arn["database"], local.kms_arn["audit"]]
      },
      {
        Sid      = "DenyOtherLogs"
        Effect   = "Deny"
        Action   = local.logs_deny
        Resource = local.other_logs["projector"]
      }
    ]
  })
}

