    old='''  tags = merge(local.tags, { Name = "${local.p}-%s", ImageId = var.'''%n
    i=s.index(old); j=s.index('\n}\n',i)
    s=s[:j]+'''

  lifecycle {
    ignore_changes = [image_config]
  }'''+s[j:]
s=s.replace('''  function_response_types            = ["ReportBatchItemFailures"]
}''','''  function_response_types            = ["ReportBatchItemFailures"]

  lifecycle {
    ignore_changes = [tags, tags_all]
  }
}''')
open(p,'w').write(s)
p='data_stores.tf'
s=open(p).read()
s=s.replace('''  tags                       = merge(local.tags, { Name = "${local.p}-valkey" })
}''','''  tags                       = merge(local.tags, { Name = "${local.p}-valkey" })

  lifecycle {
    ignore_changes = [security_group_ids, engine_version]
  }
}''')
open(p,'w').write(s)
EOF
